/** The data of `project.removed`. */
@Serializable
data class ProjectRemovedV1(
    @SerialName("project") val project: String,
    @SerialName("name") val name: String,
    @SerialName("document") val document: Document,
) : EventDataV1 {
    init {
        AwChecks.pattern(project, PATTERN_1, "project")
        AwChecks.maxLength(project, 63, "project")
        AwChecks.minLength(name, 1, "name")
        AwChecks.maxLength(name, 200, "name")
    }

    @Serializable
    data class Document(
        @SerialName("kind") val kind: String,
        @SerialName("schema") val schema: Int,
        @SerialName("slug") val slug: String,
        @SerialName("name") val name: String,
        @SerialName("devices") val devices: List<String> = emptyList(),
        @SerialName("default_agent") val defaultAgent: String = "claude",
        @SerialName("test_servers") val testServers: List<String> = emptyList(),
        @SerialName("links") val links: List<String> = emptyList(),
        @SerialName("main_repo") val mainRepo: String? = null,
        @SerialName("switches") val switches: Switches = Switches(assignNewSubtasksToDefaultDevice = false),
        @SerialName("archived") val archived: Boolean = false,
        @SerialName("added_at") val addedAt: String? = null,
        @SerialName("permission_mode") val permissionMode: String = "skip",
    ) {
        init {
            AwChecks.equal(kind, "project", "kind")
            AwChecks.equal(schema, 1, "schema")
            AwChecks.pattern(slug, PATTERN_1, "slug")
            AwChecks.maxLength(slug, 63, "slug")
            AwChecks.minLength(name, 1, "name")
            AwChecks.maxLength(name, 200, "name")
            devices.forEachIndexed { index, item ->
                AwChecks.pattern(item, PATTERN_1, "devices" + "." + index)
                AwChecks.maxLength(item, 63, "devices" + "." + index)
            }
            AwChecks.pattern(defaultAgent, PATTERN_23, "default_agent")
            testServers.forEachIndexed { index, item ->
                AwChecks.pattern(item, PATTERN_4, "test_servers" + "." + index)
                AwChecks.maxLength(item, 63, "test_servers" + "." + index)
            }
            links.forEachIndexed { index, item ->
                AwChecks.minLength(item, 1, "links" + "." + index)
            }
            if (mainRepo != null) {
                AwChecks.minLength(mainRepo, 1, "main_repo")
            }
            if (addedAt != null) {
                AwChecks.pattern(addedAt, PATTERN_24, "added_at")
                AwChecks.hlc(addedAt, "added_at")
            }
            AwChecks.oneOf(permissionMode, VALUES_6, "permission_mode")
        }

        @Serializable
        data class Switches(
            @SerialName("assign_new_subtasks_to_default_device") val assignNewSubtasksToDefaultDevice: Boolean = false,
        )
    }
}

